+/*
+ * @test
+ * @bug 8390337
+ * @summary Test C2 compilation of an inlined profiled acmp with a null operand
+ * @enablePreview
+ * @library /test/lib
+ * @run main ${test.main.class}
+ * @run main/othervm -Xbatch ${test.main.class}
+ */
+
+import jdk.test.lib.Asserts;
+
+public class TestACmpWithNullCheckTrap {
+    static Boolean getNull() {
+        return null;
+    }
+
+    static boolean test1(Object object) {
+        return object == Boolean.TRUE;
+    }
+
+    static boolean test2(Object object) {
+        return object == Boolean.TRUE;
+    }
+
+    static boolean testConstantNull1() {
+        return test1(getNull());
+    }
+
+    static boolean testConstantNull2() {
+        return test2(getNull());
+    }
+
+    public static void main(String[] args) {
+        Object obj1 = new Object();
+        Object obj2 = "42";
+
+        // Profile the acmp with identity classes so the operand is known not to be a value object
+        for (int i = 0; i < 12_000; i++) {
+            Asserts.assertFalse(test1(obj1));
+            Asserts.assertFalse(test1(obj2));
+            Asserts.assertFalse(test2(obj1));
+        }
+
+        // Compile test with its profiled operand replaced by a constant null value
+        for (int i = 0; i < 12_000; i++) {
+            Asserts.assertFalse(testConstantNull1());
+            Asserts.assertFalse(testConstantNull2());
+        }
+    }
+}
